target.css:
:root {
  --paper: #fffdf8;
  --ink: #24334a;
  --muted: #68778a;
  --line: #d5dce3;
  --blue: #2563a6;
}

.ink-slip {
  box-sizing: border-box;
  width: 430px;
  padding: 16px 18px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 14px;
}

.eyebrow {
  margin: 0 0 7px;
  color: var(--blue);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.ink-slip h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1.1;
}

.detail {
  margin: 7px 0 14px;
  color: var(--muted);
  font-size: 14px;
}

.ink-slip footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.swatch {
  color: var(--blue);
  font-size: 11px;
  font-weight: 700;
}

.ink-slip button {
  padding: 6px 11px;
  color: var(--paper);
  background: var(--blue);
  border: 1px solid var(--blue);
  border-radius: 7px;
  font-weight: 700;
}
